<section class="card narrow"><h2><?= user()['must_change_password']?'Thiết lập mật khẩu riêng':'Bảo vệ tài khoản' ?></h2><p class="muted">Mật khẩu mới dài 12–72 byte. Không dùng lại mật khẩu tạm.</p><form method="post" class="form-stack" id="password-form"><?php csrf_field() ?><label for="current_password">Mật khẩu hiện tại</label><input id="current_password" name="current_password" type="password" maxlength="72" autocomplete="current-password" required><label for="password">Mật khẩu mới</label><input id="password" name="password" type="password" minlength="12" maxlength="72" autocomplete="new-password" required><label for="confirm_password">Xác nhận mật khẩu mới</label><input id="confirm_password" name="confirm_password" type="password" minlength="12" maxlength="72" autocomplete="new-password" required><button class="button" id="change-password">Lưu mật khẩu</button></form></section>
